#include <algorithm>
#include <array>
#include <cassert>
#include <chrono>
#include <cstdint>
#include <deque>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>
using U=uint64_t;
constexpr int K=21,W=20;
constexpr U MASK=(U(1)<<42)-1,SALT=2363035971221ULL,ODD=2949826092126892291ULL;
constexpr U ANCHOR_BUDGET=5000000,CANDIDATE_BUDGET=2000000;
const char*METHODS[]={"kssd_array","xor","bare42","bare64"};
const char*POLICIES[]={"unfiltered","copycap1000"};
int base(char c){switch(c){case'A':case'a':return 0;case'C':case'c':return 1;case'G':case'g':return 2;case'T':case't':return 3;default:return -1;}}
char upper(char c){int b=base(c);return b<0?'N':"ACGT"[b];}
std::vector<std::string>split(const std::string&s,char delimiter){std::vector<std::string>v;std::string x;for(char c:s){if(c==delimiter){v.push_back(x);x.clear();}else if(c!='\r')x+=c;}v.push_back(x);return v;}
struct Record{std::string id,seq;U offset;};
std::vector<Record>read_ref(const std::string&path){std::ifstream f(path);if(!f)throw std::runtime_error("reference missing");std::vector<Record>r;std::string line;while(std::getline(f,line)){if(line.empty())continue;if(line[0]=='>'){std::string id=line.substr(1);id=id.substr(0,id.find_first_of(" \t\r"));r.push_back({id,"",0});}else{if(r.empty())throw std::runtime_error("FASTA header missing");for(char c:line)if(c!='\r'&&c!=' '&&c!='\t')r.back().seq+=upper(c);}}U offset=0;for(auto&q:r){q.offset=offset;offset+=q.seq.size();}if(r.size()!=2||r[0].id!="chr21"||r[1].id!="chr22"||offset>=U(1)<<31)throw std::runtime_error("wrong reference scope/packing");return r;}
struct Query{std::string id,origin,cohort,chrom,seq,rc,strand;U start;int L,rep,nmut;double rate;bool trace=false;};
std::vector<Query>read_queries(const std::string&path){std::ifstream f(path);if(!f)throw std::runtime_error("queries missing");std::string line;std::getline(f,line);auto h=split(line,'\t');std::map<std::string,int>header;for(size_t i=0;i<h.size();i++)header[h[i]]=i;auto at=[&](const std::vector<std::string>&a,const std::string&k){return a.at(header.at(k));};std::vector<Query>q;std::map<std::pair<std::string,std::string>,std::set<std::string>>traceorigins;while(std::getline(f,line)){auto a=split(line,'\t');Query r;r.id=at(a,"read_id");r.origin=at(a,"origin_id");r.cohort=at(a,"cohort");r.chrom=at(a,"chromosome");r.start=std::stoull(at(a,"true_start0"));r.L=std::stoi(at(a,"read_length"));r.strand=at(a,"true_strand");r.rate=std::stod(at(a,"substitution_rate"));r.rep=std::stoi(at(a,"replicate"));r.nmut=std::stoi(at(a,"n_substitutions"));r.seq=at(a,"sequence");if(int(r.seq.size())!=r.L||(r.strand!="+"&&r.strand!="-"))throw std::runtime_error("query shape");r.rc.resize(r.seq.size());for(int i=0;i<r.L;i++){int b=base(r.seq[i]);if(b<0)throw std::runtime_error("ambiguous query");r.seq[i]="ACGT"[b];r.rc[r.L-1-i]="TGCA"[b];}auto&selected=traceorigins[{r.cohort,r.chrom}];if(selected.count(r.origin)||selected.size()<8){selected.insert(r.origin);r.trace=true;}q.push_back(std::move(r));}return q;}
std::array<uint16_t,16384>read_table(const std::string&path){std::ifstream f(path,std::ios::binary);std::array<uint16_t,16384>t;std::array<bool,16384>seen{};for(auto&x:t){unsigned char z[2]={};f.read(reinterpret_cast<char*>(z),2);x=U(z[0])|(U(z[1])<<8);if(x>=16384||seen[x])throw std::runtime_error("P7 not permutation");seen[x]=true;}if(!f||f.peek()!=EOF)throw std::runtime_error("P7 byte length");return t;}
U rank_key(U x,int method,const std::array<uint16_t,16384>&p){if(method==0)return(U(p[x>>28])<<28)|(U(p[(x>>14)&16383])<<14)|p[x&16383];if(method==1)return x^SALT;if(method==2)return(x*ODD)&MASK;if(method==3)return x*ODD;throw std::runtime_error("method");}
struct Posting{U key;uint32_t loc,padding=0;};
static_assert(sizeof(Posting)==16,"posting layout");
bool posting_less(const Posting&a,const Posting&b){return a.key<b.key||(a.key==b.key&&a.loc<b.loc);}
struct Entry{U key,rank,pos;uint8_t ori;};
template<class F>void kmers(const std::string&s,U offset,F emit){U f=0,rc=0;int valid=0;for(U i=0;i<s.size();i++){int b=base(s[i]);if(b<0){f=rc=0;valid=0;continue;}f=((f<<2)|b)&MASK;rc=(rc>>2)|(U(3-b)<<40);valid++;if(valid>=K)emit(std::min(f,rc),offset+i-K+1,uint8_t(f>rc));}}
template<class F>void minimizers(const std::string&s,U offset,int method,const std::array<uint16_t,16384>&p,F emit){std::deque<Entry>d;U f=0,rc=0,last=0;bool emitted=false;int valid=0;for(U i=0;i<s.size();i++){int b=base(s[i]);if(b<0){d.clear();f=rc=0;valid=0;continue;}f=((f<<2)|b)&MASK;rc=(rc>>2)|(U(3-b)<<40);valid++;if(valid<K)continue;U pos=offset+i-K+1,key=std::min(f,rc),rank=rank_key(key,method,p);while(!d.empty()&&d.back().rank>rank)d.pop_back();d.push_back({key,rank,pos,uint8_t(f>rc)});while(!d.empty()&&d.front().pos+W<=pos)d.pop_front();if(valid<K+W-1)continue;U minrank=d.front().rank;for(auto&e:d){if(e.rank!=minrank)break;if(!emitted||e.pos>last){emit(e.key,e.pos,e.ori);last=e.pos;emitted=true;}}}}
void flush(std::ofstream&f,const std::string&name){f.flush();if(!f)throw std::runtime_error("write failed "+name);}
std::vector<U>word_counts(const std::vector<Record>&refs,const std::string&cache){std::string path=cache+"/all_canonical21_keys.bin";std::vector<U>keys;if(std::filesystem::exists(path)){std::ifstream f(path,std::ios::binary);char magic[8];U n;f.read(magic,8);f.read(reinterpret_cast<char*>(&n),8);if(!f||std::string(magic,8)!="RK21FREQ")throw std::runtime_error("frequencycacheheader");keys.resize(n);f.read(reinterpret_cast<char*>(keys.data()),n*8);if(!f||f.peek()!=EOF)throw std::runtime_error("frequencycachelength");return keys;}keys.reserve(80000000);for(auto&r:refs)kmers(r.seq,r.offset,[&](U key,U,uint8_t){keys.push_back(key);});std::cerr<<"Sorting full-reference canonical frequency index n="<<keys.size()<<'\n';std::sort(keys.begin(),keys.end());std::ofstream f(path+".tmp",std::ios::binary);f.write("RK21FREQ",8);U n=keys.size();f.write(reinterpret_cast<const char*>(&n),8);f.write(reinterpret_cast<const char*>(keys.data()),keys.size()*8);flush(f,path);f.close();std::filesystem::rename(path+".tmp",path);return keys;}
std::vector<Posting>ref_index(const std::vector<Record>&refs,int method,const std::array<uint16_t,16384>&p,const std::string&cache){std::string path=cache+"/"+METHODS[method]+"_minimizers.bin";std::vector<Posting>index;if(std::filesystem::exists(path)){std::ifstream f(path,std::ios::binary);char magic[8];U n;f.read(magic,8);f.read(reinterpret_cast<char*>(&n),8);if(!f||std::string(magic,8)!="RMIN21A1")throw std::runtime_error("indexheader");index.resize(n);f.read(reinterpret_cast<char*>(index.data()),n*sizeof(Posting));if(!f||f.peek()!=EOF)throw std::runtime_error("indexlength");return index;}index.reserve(10000000);for(auto&r:refs)minimizers(r.seq,r.offset,method,p,[&](U key,U pos,uint8_t ori){index.push_back({key,uint32_t((pos<<1)|ori),0});});std::sort(index.begin(),index.end(),posting_less);std::ofstream f(path+".tmp",std::ios::binary);f.write("RMIN21A1",8);U n=index.size();f.write(reinterpret_cast<const char*>(&n),8);f.write(reinterpret_cast<const char*>(index.data()),index.size()*sizeof(Posting));flush(f,path);f.close();std::filesystem::rename(path+".tmp",path);std::cerr<<METHODS[method]<<" native reference postings="<<index.size()<<'\n';return index;}
int record_of(U global,const std::vector<Record>&refs){return global>=refs[1].offset?1:0;}
int hamming(const std::string&sequence,U start,const std::vector<Record>&refs){int record=record_of(start,refs);U local=start-refs[record].offset;if(local+sequence.size()>refs[record].seq.size())throw std::runtime_error("candidate interval crossed chromosome");int distance=0;const char*a=sequence.data(),*b=refs[record].seq.data()+local;for(size_t i=0;i<sequence.size();i++)distance+=a[i]!=b[i];return distance;}
struct Group{U key;std::vector<uint32_t>qloc;size_t begin,end;U copies;bool allowed;};
struct Candidate{uint32_t loc;uint16_t votes;int hamming=-1;};
struct Result{std::string status="unmapped",reason="";U raw=0,n_candidates=0,n_eligible=0,seed_words=0,seed_positions=0,filtered_words=0;std::vector<Candidate>candidate;int best=-1,runnerup=-1,nbest=0;uint32_t chosen=0;};
struct BothResult{std::array<Result,2>r;std::vector<Group>groups;};
BothResult place(const std::string&seq,const std::string&rc,const std::vector<Posting>&qseeds,const std::vector<Posting>&index,const std::vector<U>&frequency,const std::vector<Record>&refs){
 BothResult out;std::vector<Posting>sorted=qseeds;std::sort(sorted.begin(),sorted.end(),posting_less);std::vector<Group>groups;for(size_t i=0;i<sorted.size();){size_t j=i+1;while(j<sorted.size()&&sorted[j].key==sorted[i].key)j++;U key=sorted[i].key;auto lo=std::lower_bound(index.begin(),index.end(),key,[](const Posting&a,U k){return a.key<k;});auto hi=std::upper_bound(lo,index.end(),key,[](U k,const Posting&a){return k<a.key;});auto fl=std::lower_bound(frequency.begin(),frequency.end(),key);auto fh=std::upper_bound(fl,frequency.end(),key);Group g{key,{},size_t(lo-index.begin()),size_t(hi-index.begin()),U(fh-fl),U(fh-fl)<=1000};for(size_t z=i;z<j;z++)g.qloc.push_back(sorted[z].loc);groups.push_back(std::move(g));i=j;}
 for(auto&g:groups){U hits=U(g.end-g.begin)*g.qloc.size();out.r[0].raw+=hits;out.r[0].seed_words++;out.r[0].seed_positions+=g.qloc.size();if(g.allowed){out.r[1].raw+=hits;out.r[1].seed_words++;out.r[1].seed_positions+=g.qloc.size();}else out.r[1].filtered_words++;}
 for(int policy=0;policy<2;policy++)if(out.r[policy].raw>ANCHOR_BUDGET){out.r[policy].status="over_budget";out.r[policy].reason="raw_anchor_pairs";}
 bool all=out.r[0].status!="over_budget",filtered=out.r[1].status!="over_budget";if(!all&&!filtered){out.groups=std::move(groups);return out;}
 std::vector<U>pairs;pairs.reserve(size_t(all?out.r[0].raw:out.r[1].raw));for(size_t gi=0;gi<groups.size();gi++){auto&g=groups[gi];if(!all&&!g.allowed)continue;for(size_t ri=g.begin;ri<g.end;ri++){uint32_t ref=index[ri].loc;U rpos=ref>>1;int record=record_of(rpos,refs);for(uint32_t q:g.qloc){U qpos=q>>1;unsigned strand=(q^ref)&1;int64_t start=int64_t(rpos)-int64_t(strand?seq.size()-K-qpos:qpos);if(start<int64_t(refs[record].offset)||U(start)+seq.size()>refs[record].offset+refs[record].seq.size())continue;uint32_t loc=uint32_t((U(start)<<1)|strand);pairs.push_back((U(loc)<<32)|gi);}}}
 std::sort(pairs.begin(),pairs.end());for(size_t i=0;i<pairs.size();){uint32_t loc=pairs[i]>>32;size_t j=i;int votes=0,filteredvotes=0;U previous=~U(0);while(j<pairs.size()&&uint32_t(pairs[j]>>32)==loc){U gi=uint32_t(pairs[j]);if(gi!=previous){votes++;filteredvotes+=groups[gi].allowed;previous=gi;}j++;}for(int policy=0;policy<2;policy++){if((policy==0&&!all)||(policy==1&&!filtered))continue;int n=policy==0?votes:filteredvotes;if(!n)continue;auto&r=out.r[policy];r.n_candidates++;r.n_eligible+=n>=2;if(r.n_candidates<=CANDIDATE_BUDGET)r.candidate.push_back({loc,uint16_t(n),-1});else if(r.n_candidates==CANDIDATE_BUDGET+1){r.candidate.clear();r.status="over_budget";r.reason="distinct_candidate_diagonals";}}i=j;}
 for(int policy=0;policy<2;policy++){auto&r=out.r[policy];if(r.status=="over_budget")continue;int best=1000000,second=1000000,nbest=0;uint32_t chosen=0;for(auto&c:r.candidate)if(c.votes>=2){c.hamming=hamming((c.loc&1)?rc:seq,c.loc>>1,refs);int d=c.hamming;if(d<best){second=best;best=d;nbest=1;chosen=c.loc;}else if(d==best){second=best;nbest++;}else if(d<second)second=d;}if(best<1000000){r.best=best;r.runnerup=second<1000000?second:-1;r.nbest=nbest;}if(best<=int(seq.size()/5)){if(nbest==1){r.status="unique";r.chosen=chosen;}else r.status="ambiguous";}}
 out.groups=std::move(groups);return out;
}
struct TruthDiagnostics{std::array<int,2>votes{};std::array<U,2>inside_raw{};};
TruthDiagnostics truth_diagnostics(const Query&q,const std::vector<Group>&groups,const std::vector<Posting>&index,const std::vector<Record>&refs){int record=q.chrom==refs[0].id?0:1;U start=refs[record].offset+q.start;TruthDiagnostics d;for(auto&g:groups){auto begin=index.begin()+g.begin,end=index.begin()+g.end;auto lo=std::lower_bound(begin,end,uint32_t(start<<1),[](const Posting&a,uint32_t loc){return a.loc<loc;});auto hi=std::lower_bound(lo,end,uint32_t((start+q.L)<<1),[](const Posting&a,uint32_t loc){return a.loc<loc;});U inside=U(hi-lo)*g.qloc.size();d.inside_raw[0]+=inside;if(g.allowed)d.inside_raw[1]+=inside;bool vote=false;for(uint32_t loc:g.qloc){U qp=loc>>1;U rp=start+(q.strand=="-"?q.L-K-qp:qp);unsigned orientation=(loc&1)^(q.strand=="-");uint32_t target=(rp<<1)|orientation;auto hit=std::lower_bound(begin,end,target,[](const Posting&a,uint32_t x){return a.loc<x;});if(hit!=end&&hit->loc==target){vote=true;break;}}if(vote){d.votes[0]++;if(g.allowed)d.votes[1]++;}}return d;}
void write_header(std::ostream&f){f<<"read_id,origin_id,cohort,chromosome,true_start0,read_length,true_strand,substitution_rate,replicate,n_substitutions,method,policy,status,mapping_status,chosen_chromosome,chosen_start0,chosen_strand,chosen_hamming,runnerup_hamming,n_best,query_seed_words,query_seed_positions,filtered_words,raw_anchor_pairs,n_distinct_candidates,n_eligible_candidates,origin_seed_votes,origin_candidate_available,offtarget_eligible_candidates,source_raw_anchor_pairs,offtarget_raw_anchor_pairs,candidate_diagnostics_complete,true_hamming,wrong_distance_relation,over_budget_reason\n";}
void write_row(std::ostream&f,const Query&q,int method,int policy,const Result&r,const TruthDiagnostics&diagnostic,const std::vector<Record>&refs){int true_record=q.chrom==refs[0].id?0:q.chrom==refs[1].id?1:-1;if(true_record<0)throw std::runtime_error("truthchr");U true_start=refs[true_record].offset+q.start;uint32_t true_loc=uint32_t((true_start<<1)|(q.strand=="-"));int td=hamming(q.strand=="-"?q.rc:q.seq,true_start,refs);if(td!=q.nmut)throw std::runtime_error("true Hamming != reportedmutationcount");std::string outcome=r.status=="over_budget"?"unmapped":r.status;int votes=diagnostic.votes[policy];bool origin_available=votes>=2;bool diagnostic_complete=r.reason!="raw_anchor_pairs";int64_t off=diagnostic_complete?int64_t(r.n_eligible)-origin_available:-1;std::string chosenchr="",chosenstart="",chosenstrand="",relation="";if(r.status=="unique"){U start=r.chosen>>1;int record=record_of(start,refs);chosenchr=refs[record].id;chosenstart=std::to_string(start-refs[record].offset);chosenstrand=(r.chosen&1)?"-":"+";outcome=r.chosen==true_loc?"correct_origin_unique":"wrong_origin_unique";if(outcome=="wrong_origin_unique")relation=r.best<td?"less_than_origin":r.best==td?"equal_to_origin":"greater_than_origin";}
 f<<q.id<<','<<q.origin<<','<<q.cohort<<','<<q.chrom<<','<<q.start<<','<<q.L<<','<<q.strand<<','<<q.rate<<','<<q.rep<<','<<q.nmut<<','<<METHODS[method]<<','<<POLICIES[policy]<<','<<outcome<<','<<r.status<<','<<chosenchr<<','<<chosenstart<<','<<chosenstrand<<','<<r.best<<','<<r.runnerup<<','<<r.nbest<<','<<r.seed_words<<','<<r.seed_positions<<','<<r.filtered_words<<','<<r.raw<<','<<r.n_candidates<<','<<r.n_eligible<<','<<votes<<','<<origin_available<<','<<off<<','<<diagnostic.inside_raw[policy]<<','<<r.raw-diagnostic.inside_raw[policy]<<','<<diagnostic_complete<<','<<td<<','<<relation<<','<<r.reason<<'\n';}
void write_trace(std::ostream&f,const Query&q,int method,int policy,const Result&r,const std::vector<Record>&refs){for(auto&c:r.candidate)if(c.votes>=2){U start=c.loc>>1;int record=record_of(start,refs);f<<q.id<<','<<q.origin<<','<<q.cohort<<','<<q.rate<<','<<q.L<<','<<q.strand<<','<<q.rep<<','<<METHODS[method]<<','<<POLICIES[policy]<<','<<refs[record].id<<','<<start-refs[record].offset<<','<<((c.loc&1)?"-":"+")<<','<<c.votes<<','<<c.hamming<<','<<(c.hamming==r.best)<<','<<(r.status=="unique"&&c.loc==r.chosen)<<'\n';}}
int main(int argc,char**argv){try{
 if(argc!=6)throw std::runtime_error("usage: mapper REFERENCE_FA QUERIES_TSV FIXED_P7 CACHE_DIR OUTPUT_DIR");
 auto refs=read_ref(argv[1]);auto queries=read_queries(argv[2]);auto p=read_table(argv[3]);std::string cache=argv[4],output=argv[5];std::filesystem::create_directories(cache);std::filesystem::create_directories(output);auto frequency=word_counts(refs,cache);
 std::ofstream manifest(cache+"/reference_manifest.json");manifest<<"{\"k\":21,\"w\":20,\"posting_bytes\":16,\"posting_format\":\"u64LEkey,u32LEloc=(globalpos<<1)|orientation,u32LEzero; indexheader8bytesRMIN21A1+u64LEn\",\"frequency_header\":\"RK21FREQ8bytes+u64LEn+sortedu64LEcanonicalkeys\",\"n_full_reference_word_positions\":"<<frequency.size()<<",\"records\":[";for(size_t i=0;i<refs.size();i++){if(i)manifest<<',';manifest<<"{\"id\":\""<<refs[i].id<<"\",\"offset\":"<<refs[i].offset<<",\"length\":"<<refs[i].seq.size()<<'}';}manifest<<"]}\n";flush(manifest,"refmanifest");std::ofstream runtime(output+"/runtime.csv");runtime<<"method,n_reference_postings,n_reads,index_seconds,mapping_seconds\n";
 for(int method=0;method<4;method++){auto t0=std::chrono::steady_clock::now();auto index=ref_index(refs,method,p,cache);auto t1=std::chrono::steady_clock::now();std::string path=output+"/placements_"+METHODS[method]+".csv";std::ofstream out(path+".tmp"),trace(output+"/candidate_trace_"+METHODS[method]+".csv.tmp");out<<std::setprecision(17);trace<<std::setprecision(17);write_header(out);trace<<"read_id,origin_id,cohort,substitution_rate,read_length,true_strand,replicate,method,policy,candidate_chromosome,candidate_start0,candidate_strand,distinct_word_votes,hamming,best_hamming,chosen\n";
  for(size_t qi=0;qi<queries.size();qi++){auto&q=queries[qi];std::vector<Posting>seeds;seeds.reserve(q.L/5);minimizers(q.seq,0,method,p,[&](U key,U pos,uint8_t ori){seeds.push_back({key,uint32_t((pos<<1)|ori),0});});auto result=place(q.seq,q.rc,seeds,index,frequency,refs);auto diagnostic=truth_diagnostics(q,result.groups,index,refs);for(int policy=0;policy<2;policy++){write_row(out,q,method,policy,result.r[policy],diagnostic,refs);if(q.trace)write_trace(trace,q,method,policy,result.r[policy],refs);}if((qi+1)%2048==0)std::cerr<<METHODS[method]<<" reads="<<qi+1<<'/'<<queries.size()<<'\n';}
  flush(out,path);flush(trace,"trace");out.close();trace.close();std::filesystem::rename(path+".tmp",path);std::filesystem::rename(output+"/candidate_trace_"+METHODS[method]+".csv.tmp",output+"/candidate_trace_"+METHODS[method]+".csv");auto t2=std::chrono::steady_clock::now();runtime<<METHODS[method]<<','<<index.size()<<','<<queries.size()<<','<<std::chrono::duration<double>(t1-t0).count()<<','<<std::chrono::duration<double>(t2-t1).count()<<'\n';flush(runtime,"runtime");std::cerr<<METHODS[method]<<" complete\n";
 }
 return 0;
}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 1;}}
